The supplied files need changes to define the allergy types and implement bitmask-based allergy checks. Unknown score bits are ignored because only the eight listed allergens are included in `get_allergies()`.

allergies.h
```
#if !defined(ALLERGIES_H)
#define ALLERGIES_H

#include <unordered_set>

namespace allergies {

enum class allergen {
    eggs,
    peanuts,
    shellfish,
    strawberries,
    tomatoes,
    chocolate,
    pollen,
    cats
};

class allergy_test {
public:
    explicit allergy_test(unsigned score);

    bool is_allergic_to(allergen item) const;
    std::unordered_set<allergen> get_allergies() const;

private:
    unsigned score_;
};

}  // namespace allergies

#endif  // ALLERGIES_H
```

allergies.cpp
```
#include "allergies.h"

namespace allergies {

namespace {

unsigned allergen_value(allergen item)
{
    return 1u << static_cast<unsigned>(item);
}

}  // namespace

allergy_test::allergy_test(unsigned score) : score_(score)
{
}

bool allergy_test::is_allergic_to(allergen item) const
{
    return (score_ & allergen_value(item)) != 0;
}

std::unordered_set<allergen> allergy_test::get_allergies() const
{
    std::unordered_set<allergen> result;

    for (unsigned index = 0; index < 8; ++index) {
        const auto item = static_cast<allergen>(index);
        if (is_allergic_to(item)) {
            result.emplace(item);
        }
    }

    return result;
}

}  // namespace allergies
